function compactReports(){
  let reports=$('reports');if(!reports||reports.dataset.compacted==='1')return;reports.dataset.compacted='1';
  [...reports.children].forEach((child,i)=>{if(child.tagName==='DETAILS')return;let d=document.createElement('details');d.className='compact-collapsible';if(i===0)d.open=true;let s=document.createElement('summary');let h=child.querySelector('h3');s.textContent=h?.textContent||(['گزارش خروج انبار','لیست مشتریان','گزارش دستگاه‌ها'][i]||'گزارش');let body=document.createElement('div');body.dataset.collapseBody='1';child.parentNode.insertBefore(d,child);d.append(s,body);body.appendChild(child)})
}

