function compactReports(){
  // Keep one report sheet without unrelated accordion labels.
  const reports=$('reports');
  if(reports)reports.dataset.compacted='1';
}
window.printExitReportPdf=function(){
  const table=$('repBody')?.closest('table');
  if(!table)return;
  const copy=table.cloneNode(true);
  copy.querySelectorAll('button').forEach(button=>{
    button.replaceWith(document.createTextNode(button.textContent.replace(/[▼↕▲]/g,'').trim()));
  });
  const popup=window.open('','_blank');
  if(!popup){alert('برای دریافت PDF، اجازهٔ باز شدن پنجرهٔ خروجی را بدهید.');return;}
  popup.document.write('<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>گزارش خروج</title><style>@page{size:A4 landscape;margin:10mm}body{font-family:Tahoma,Arial,sans-serif;color:#102a43;margin:0;direction:rtl}h1{font-size:18px;margin:0 0 12px;text-align:center}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #aab8c6;padding:7px;text-align:right;vertical-align:top}thead{display:table-header-group}th{background:#edf2f7}tr{break-inside:avoid}button{display:none}</style></head><body><h1>گزارش خروج</h1>'+copy.outerHTML+'</body></html>');
  popup.document.close();
  popup.focus();
  popup.print();
}
